import{_ as e,a as r,o as a,a2 as o}from"./chunks/framework.DCcmcJcL.js";const h=JSON.parse('{"title":"Attribute Input Type","description":"","frontmatter":{},"headers":[],"relativePath":"attribute/attribute-input.md","filePath":"attribute/attribute-input.md","lastUpdated":1789390368000}'),i={name:"attribute/attribute-input.md"};function d(n,t,s,u,p,c){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="attribute-input-type" tabindex="-1">Attribute Input Type <a class="header-anchor" href="#attribute-input-type" aria-label="Permalink to &quot;Attribute Input Type&quot;">​</a></h1><p>Attributes can have different input types that determine not only how you enter the values for the attribute, but also how shoppers can select attributes in the case of options, or enter values.</p><p>Product Attributes are a set of characteristics that define a particular product or a group of goods. This means size, color, flavor, package type, etc. constitute attributes. Product attributes are not just about the general description of a product, but they speak about the value of products that makes it unique.</p><table tabindex="0"><thead><tr><th>Attribute Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Text</strong></td><td>A single-line input field for text.</td></tr><tr><td><strong>Textarea</strong></td><td>A multiple-line input field for entering paragraphs of text, such as a product description.</td></tr><tr><td><strong>Price</strong></td><td>A price field in addition to the predefined price attributes: Price, Special Price and Cost.</td></tr><tr><td><strong>Boolean</strong></td><td>A toggle switch that is either on or off.</td></tr><tr><td><strong>Select</strong></td><td>A drop-down list from which one value is selected.</td></tr><tr><td><strong>Multiselect</strong></td><td>A drop-down list of values that accepts multiple selections.</td></tr><tr><td><strong>Datetime</strong></td><td>A date and time value in the preferred format and time zone.</td></tr><tr><td><strong>Date</strong></td><td>A date value in the preferred format.</td></tr><tr><td><strong>Image</strong></td><td>An image upload.</td></tr><tr><td><strong>File</strong></td><td>A file upload.</td></tr><tr><td><strong>Checkbox</strong></td><td>A set of options of which any number can be ticked.</td></tr></tbody></table>',4)]))}const f=e(i,[["render",d]]);export{h as __pageData,f as default};
